package com.tripmateai.service.impl;
import com.tripmateai.dto.request.activity.*; import com.tripmateai.dto.response.activity.ActivityResponse; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.ActivityMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.ActivityService; import jakarta.persistence.EntityManager; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class ActivityServiceImpl implements ActivityService {private final ActivityRepository activities;private final ItineraryRepository itineraries;private final TripRepository trips;private final EntityManager entityManager; private User user(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal x))throw new UnauthorizedException("Authentication required");return x.user();} private Itinerary itinerary(Long id){var i=itineraries.findById(id).orElseThrow(()->new ResourceNotFoundException("Itinerary not found"));if(!i.getTrip().getUser().getId().equals(user().getId()))throw new UnauthorizedException("You do not have access to this itinerary");return i;} private Activity activity(Long id){var a=activities.findById(id).orElseThrow(()->new ResourceNotFoundException("Activity not found"));if(!a.getItinerary().getTrip().getUser().getId().equals(user().getId()))throw new UnauthorizedException("You do not have access to this activity");return a;} private void times(java.time.LocalTime start,java.time.LocalTime end){if(start!=null&&end!=null&&end.isBefore(start))throw new BadRequestException("End time cannot be before start time");} public ActivityResponse create(Long itineraryId,CreateActivityRequest r){if(!Objects.equals(r.itineraryId(),itineraryId))throw new BadRequestException("Itinerary ID must match path");times(r.startTime(),r.endTime());var i=itinerary(itineraryId);var a=new Activity();a.setItinerary(i);a.setTitle(r.title());a.setType(r.type());a.setSortOrder(r.sortOrder());a.setStartTime(r.startTime());a.setEndTime(r.endTime());return ActivityMapper.toResponse(activities.save(a));} @Transactional(readOnly=true) public List<ActivityResponse> list(Long itineraryId){return activities.findByItineraryOrderBySortOrderAsc(itinerary(itineraryId)).stream().map(ActivityMapper::toResponse).toList();} @Transactional(readOnly=true) public ActivityResponse get(Long id){return ActivityMapper.toResponse(activity(id));} public ActivityResponse update(Long id,UpdateActivityRequest r){var a=activity(id);a.setTitle(r.title());a.setSortOrder(r.sortOrder());return ActivityMapper.toResponse(activities.save(a));} public void delete(Long id){activities.delete(activity(id));} public void reorder(Long itineraryId,ReorderActivitiesRequest r){var i=itinerary(itineraryId);var existing=activities.findByItineraryOrderBySortOrderAsc(i);var ids=r.activityIds();if(new HashSet<>(ids).size()!=ids.size()||ids.size()!=existing.size())throw new BadRequestException("Reorder request must contain every activity exactly once");var byId=new HashMap<Long,Activity>();existing.forEach(a->byId.put(a.getId(),a));for(int index=0;index<existing.size();index++)existing.get(index).setSortOrder(-(index+1));entityManager.flush();for(int index=0;index<ids.size();index++){var a=byId.get(ids.get(index));if(a==null)throw new BadRequestException("Activity does not belong to this itinerary");a.setSortOrder(index+1);}entityManager.flush();}}
